<?php
require_once __DIR__ . '/../../app/staff.php';
require_once __DIR__ . '/../../app/view.php';
require_once __DIR__ . '/../../app/modules.php';
$db = database(); $user = staff_user($db); $manager = $_SESSION['auth_role'] === 'manager';
$name = $manager ? $user['manager_name'] : trim($user['first_name'] . ' ' . $user['last_name']);
if ($manager) {
    $projects = db_rows($db,'SELECT id, projectName, status, endDate FROM projects WHERE company_id = ? AND (projectManager = ? OR project_manager_id = ?) ORDER BY updated_at DESC LIMIT 50',[$user['company_id'],$user['id'],$user['unique_id']]);
    $tasks = db_rows($db,'SELECT t.id,t.title,t.status,t.due_date,t.priority FROM tasks t JOIN projects p ON ' . task_project_join() . ' WHERE t.company_id = ? AND (p.projectManager = ? OR p.project_manager_id = ?) ORDER BY t.due_date LIMIT 100',[$user['company_id'],$user['id'],$user['unique_id']]);
} else {
    $projects = db_rows($db,'SELECT DISTINCT p.id,p.projectName,p.status,p.endDate FROM projects p JOIN tasks t ON ' . task_project_join() . ' WHERE t.company_id = ? AND (t.assignee = ? OR t.assignee = ?) ORDER BY p.endDate LIMIT 50',[$user['company_id'],(string)$user['id'],$user['unique_id']]);
    $tasks = db_rows($db,'SELECT id,title,status,due_date,priority FROM tasks WHERE company_id = ? AND (assignee = ? OR assignee = ?) ORDER BY due_date LIMIT 100',[$user['company_id'],(string)$user['id'],$user['unique_id']]);
}
$open = array_filter($tasks,fn($task)=>$task['status'] !== 'completed');
$overdue = array_filter($open,fn($task)=>$task['due_date'] && $task['due_date'] < date('Y-m-d'));
$department = db_one($db,'SELECT department_name FROM departments WHERE id = ? AND company_id = ?',[$user['department_id'],$user['company_id']]);
suite_start('My workspace','overview',$user);
?>
<div class="page-heading"><div><h1>My workspace</h1><p><?= e($user['company_name']) ?> · <?= count($open) ?> open <?= count($open) === 1 ? 'task' : 'tasks' ?><?= $overdue ? ' · <strong class="due overdue">' . count($overdue) . ' overdue</strong>' : '' ?></p></div></div>
<div class="dashboard-columns"><div><section class="panel" id="tasks"><div class="panel-head"><h2><?= $manager ? 'Tasks in your projects' : 'Your assigned tasks' ?></h2><span class="badge"><?= count($tasks) ?> shown</span></div><?php if (!$tasks): ?><div class="empty-state"><?= icon('task') ?><h3>No assigned tasks</h3><p><?= $manager ? 'Tasks will appear here when they are added to projects you manage.' : 'Tasks will appear here when your workspace administrator assigns work to you.' ?></p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Task</th><th>Due date</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php foreach ($tasks as $task): ?><tr><td><?= e($task['title']) ?></td><td><?= record_cell_html(['fields'=>['due_date'=>['type'=>'date']]],'due_date',$task,'','status') ?></td><td><span class="badge <?= e(stage_class($task['priority'])) ?>"><?= e($task['priority']) ?></span></td><td><?php if (!$manager): ?><form method="post" action="/users/employees/task-status.php" style="display:flex;gap:8px" data-submit><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= (int)$task['id'] ?>"><label class="sr-only" for="status-<?= (int)$task['id'] ?>">Status for <?= e($task['title']) ?></label><select class="inline-select" name="status" id="status-<?= (int)$task['id'] ?>"><?php foreach (['pending','ongoing','completed'] as $status): ?><option value="<?= $status ?>" <?= $task['status'] === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select><button type="submit" class="button small secondary">Save</button></form><?php else: ?><span class="badge <?= e(stage_class($task['status'])) ?>"><?= e($task['status']) ?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2><?= $manager ? 'Projects you manage' : 'Projects you’re part of' ?></h2></div><?php if (!$projects): ?><div class="empty-state"><?= icon('folder') ?><h3>No projects assigned</h3><p>Your assigned projects will appear here.</p></div><?php else: ?><ul class="record-list"><?php foreach ($projects as $project): ?><li><span class="record-icon"><?= icon('folder') ?></span><div><strong><?= e($project['projectName']) ?></strong><small><?= $project['endDate'] ? 'Due ' . e(date('j M Y',strtotime($project['endDate']))) : 'No due date set' ?></small></div><span class="badge <?= e(stage_class($project['status'])) ?>"><?= e($project['status'] ?: 'Planned') ?></span></li><?php endforeach; ?></ul><?php endif; ?></section></div>
<aside><section class="panel" id="profile"><div class="panel-head"><h2>Your profile</h2></div><div class="panel-body"><span class="avatar" style="margin-bottom:18px"><?= e(mb_strtoupper(mb_substr($name,0,1))) ?></span><h3><?= e($name) ?></h3><p class="subtle"><?= e($user['email']) ?></p><p><strong>Department</strong><br><?= e($department['department_name'] ?? 'Not assigned') ?></p><p><strong>Workspace code</strong><br><?= e($user['company_id']) ?></p><small class="subtle">Contact your workspace administrator to update your profile or access.</small></div></section></aside></div>
<?php suite_end(); ?>
